#!/bin/sh
# Bootstraps the self-hosted Axiom compiler.
#
#   stage 0  the C compiler (compiler/), built with make (it uses LLVM)
#   stage 1  selfhost/src compiled by stage 0 (code generated by LLVM)
#   stage 2  selfhost/src compiled by stage 1 (its own backends and linker)
#   stage 3  selfhost/src compiled by stage 2: must be bit-identical to stage 2
#
# The result is selfhost/build/axiom (stage 2), which needs nothing but
# the C library: no LLVM, no C compiler, no linker. Environment:
#   OPT     optimization level for the stages (default: -O2)
#   CROSS   1: also check that stage 2 built for the other architecture (run
#           with qemu) generates the same code as stage 2 itself
set -eu
cd "$(dirname "$0")/.."

OPT=${OPT:--O2}
CROSS=${CROSS:-0}
B=selfhost/build

stage() {
    echo "stage $3: $1 -> $2"
    start=$(date +%s)
    # shellcheck disable=SC2086
    "$1" build selfhost/src/main.ax --target=native $OPT -o "$2"
    echo "         $(($(date +%s) - start)) s, $(wc -c < "$2") bytes"
}

make -C compiler --no-print-directory
mkdir -p $B
if [ "$(uname -s)" = Darwin ]; then
    # The C compiler does not build native Mac programs (issues/0013), but it
    # builds WebAssembly: stage 1 is the self-hosted compiler for wasm32,
    # run under node, building itself for the Mac.
    echo "stage 1: compiler/build/axiom -> $B/axiom1.wasm (node) -> $B/axiom1"
    start=$(date +%s)
    # shellcheck disable=SC2086
    compiler/build/axiom build selfhost/src/main.ax --target=wasm32 $OPT -o $B/axiom1.wasm
    # shellcheck disable=SC2086
    node runtime/host.mjs $B/axiom1.wasm -- build selfhost/src/main.ax --target=native $OPT -o $B/axiom1
    echo "         $(($(date +%s) - start)) s, $(wc -c < "$B/axiom1") bytes"
else
    stage compiler/build/axiom $B/axiom1 1
fi
# (stages 2 and 3 have the same file name: a Mac executable's code
# signature holds it)
mkdir -p $B/stage2 $B/stage3
stage $B/axiom1 $B/stage2/axiom 2
stage $B/stage2/axiom $B/stage3/axiom 3

if ! cmp -s $B/stage2/axiom $B/stage3/axiom; then
    echo "bootstrap FAILED: stage 2 and stage 3 differ (the self-hosted compiler is not at a fixed point)" >&2
    exit 1
fi
echo "fixed point: stage 2 and stage 3 are bit-identical"
cp $B/stage2/axiom $B/axiom2
rm -f $B/axiom
cp $B/stage2/axiom $B/axiom

if [ "$CROSS" = 1 ]; then
    # The compiler built for the other architecture must generate the same
    # code as the native one.
    host=$(uname -m)
    other=aarch64
    [ "$host" = aarch64 ] && other=x86_64
    echo "cross: stage 2 for $other"
    $B/axiom build selfhost/src/main.ax --target=$other $OPT -o $B/axiom-$other
    # (explicit targets: --target=native would use this machine's extensions)
    $B/axiom build selfhost/src/main.ax --target=$host $OPT -o $B/axiom-generic
    qemu-$other -L /usr/$other-linux-gnu $B/axiom-$other build selfhost/src/main.ax --target=$host $OPT -o $B/axiom-cross
    if ! cmp -s $B/axiom-generic $B/axiom-cross; then
        echo "bootstrap FAILED: the $other-hosted compiler generates different code" >&2
        exit 1
    fi
    echo "cross: the $other-hosted compiler generates the same code, bit for bit"
fi

# The compiler's own unit tests.
$B/axiom test selfhost/src/util.ax --target=native
echo "built $B/axiom"
